def score_applicant(cv: dict) -> int:
    """Score an applicant 0-100. Age is not used."""
    years = cv.get("years_experience", 0)
    degree = cv.get("degree", "").lower()
    gaps = cv.get("gaps_in_employment", 0)
    postcode = cv.get("postcode")
    office_postcode = "SW1A 1AA"  # put your office address here
    distance = _distance(postcode, office_postcode)

    score = 0

    # Years of experience, capping at 20
    score += min(years, 20) * 4

    # Degree level
    if "phd" in degree or "doctor" in degree:
        score += 25
    elif "masters" in degree or "master" in degree or "mSc" in degree or "mEng" in degree:
        score += 20
    elif "bachelors" in degree or "bachelor" in degree or "ba" in degree or "bsc" in degree or "beng" in degree:
        score += 15
    elif "a levels" in degree or "ib" in degree or "high school" in degree:
        score += 5
    else:
        score += 0

    # Employment gaps, up to 5 years counted
    score += max(0, 5 - gaps) * 3

    # Distance to office (rough estimate)
    if distance is None:
        score += 5  # postcode missing; don't punish
    elif distance <= 10:
        score += 15
    elif distance <= 25:
        score += 10
    elif distance <= 50:
        score += 5
    else:
        score += 0

    return min(100, max(0, score))


def _distance(postcode1: str | None, postcode2: str) -> int | None:
    if not postcode1:
        return None
    try:
        from geopy.distance import geodesic
        from geopy.geocoders import Nominatim

        geolocator = Nominatim(user_agent="hiring_tool")
        p1 = geolocator.geocode(postcode1, exactly_one=True)
        p2 = geolocator.geocode(postcode2, exactly_one=True)
        if not (p1 and p2):
            return None
        return int(geodesic(p1.latitude, p1.longitude, p2.latitude, p2.longitude).km)
    except Exception:
        return None
```

