```python
from typing import Dict, Any, List, Optional, Union
import re


def _clean_text(value: Optional[Union[str, List[str]]]) -> str:
    if value is None:
        return ""
    if isinstance(value, list):
        return ", ".join(str(v) for v in value)
    return str(value).strip()


def _extract_int_from_text(text: str, default: int = 0) -> int:
    if not text:
        return default
    match = re.search(r"(\d+)", text)
    return int(match.group(1)) if match else default


def _dedupe_years_experience(experience_text: str) -> int:
    total = 0
    for match in re.finditer(r"(\d+)(?:\s*(?:years?|yrs?|yr|y))?", experience_text, re.IGNORECASE):
        total += int(match.group(1))
    if total > 25:
        return 25
    return max(0, total)


def _count_degrees(education_text: str) -> int:
    text = education_text.upper()
    count = 0
    if re.search(r"\b(ph\.d|doctorate|d\.ph|d\.sc)\b", text):
        count += 2
    elif re.search(r"\b(master|m\.a|m\.sc|m\.eng|m\.b\.a|m\.phil)\b", text):
        count += 1.5
    elif re.search(r"\b(bachelor|ba|bs|b\.sc|b\.eng|m\.tech)\b", text):
        count += 1
    elif re.search(r"\b(hons?|diploma|cert|nd|associate)\b", text):
        count += 0.5
    return count


def _count_gap_months(gaps: Optional[Union[str, List[str]]]) -> int:
    if gaps is None:
        return 0
    if isinstance(gaps, str):
        return _extract_int_from_text(gaps, default=0)
    return sum(_extract_int_from_text(str(g), default=0) for g in gaps)


def score_applicant(
    cv: Dict[str, Any],
    max_experience: int = 25,
    experience_factor: float = 2.5,
    degree_factor: float = 4,
    gap_penalty_per_month: float = 0.5,
    max_score: float = 100,
) -> float:
    experience = _dedupe_years_experience(_clean_text(cv.get("years_experience", "")))
    degree_score = _count_degrees(_clean_text(cv.get("degree", ""))) + _count_degrees(_clean_text(cv.get("education", "")))
    gap_months = _count_gap_months(cv.get("gaps_in_employment"))

    experience_score = min(experience, max_experience) * experience_factor
    degree_score *= degree_factor
    gap_penalty = gap_months * gap_penalty_per_month

    total = experience_score + degree_score - gap_penalty
    return round(max(0, min(total, max_score)), 1)


def score_applicants_batch(
    applicants: List[Dict[str, Any]],
    **kw,
) -> List[Dict[str, Any]]:
    scores = []
    for app in applicants:
        app["score"] = score_applicant(app, **kw)
        scores.append(app)
    return sorted(scores, key=lambda a: a["score"], reverse=True)
